import React, { useEffect, useRef, useState } from 'react';
import './Galaxy.css';
import NavBar from '../Navigation/Navigation';

const GALAXY_LANDMARKS = [
  { id: 'core', name: 'Sagittarius A* (Galactic Core)', dist: '26,000 light-years', desc: 'The supermassive black hole powering our Milky Way galaxy, surrounded by a swirling accretion disk of superheated plasma.', color: '#ffd166' },
  { id: 'orion', name: 'Orion Nebula & Solar System', dist: '1,344 light-years', desc: 'Our home stellar neighborhood! A vibrant star-forming region glowing with gas clouds and protostars.', color: '#00d2ff' },
  { id: 'andromeda', name: 'Andromeda Outer Spiral Arm', dist: '2.5 million light-years', desc: 'The vast outer spiral arm rich in massive blue giant stars and cosmic dust lanes.', color: '#4ef0d0' },
  { id: 'carina', name: 'Carina Stellar Nursery', dist: '8,500 light-years', desc: 'One of the largest and brightest nebulae in the night sky, crafting giant stars 100x larger than our sun.', color: '#ff6b6b' }
];

export default function Galaxy() {
  const canvasRef = useRef(null);
  const [speed, setSpeed] = useState(1);
  const [warpMode, setWarpMode] = useState(false);
  const [activeLandmark, setActiveLandmark] = useState(GALAXY_LANDMARKS[0]);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let animationFrameId;
    let width = (canvas.width = canvas.parentElement.clientWidth);
    let height = (canvas.height = canvas.parentElement.clientHeight || 550);

    const handleResize = () => {
      if (canvas && canvas.parentElement) {
        width = canvas.width = canvas.parentElement.clientWidth;
        height = canvas.height = canvas.parentElement.clientHeight || 550;
      }
    };
    window.addEventListener('resize', handleResize);

    // Generate 1200 Galaxy Star Particles
    const starCount = 1200;
    const stars = [];
    const numArms = 4;
    const armWidth = 0.5;

    for (let i = 0; i < starCount; i++) {
      const distance = Math.pow(Math.random(), 2) * Math.min(width, height) * 0.42;
      const angle = (i % numArms) * ((2 * Math.PI) / numArms) + distance * 0.008 + (Math.random() - 0.5) * armWidth;

      const colors = ['#ffffff', '#4ef0d0', '#00d2ff', '#ffd166', '#a060ff', '#ff6b6b'];
      const color = colors[Math.floor(Math.random() * colors.length)];

      stars.push({
        x: Math.cos(angle) * distance,
        y: Math.sin(angle) * distance,
        z: (Math.random() - 0.5) * 120,
        size: Math.random() * 2 + 0.6,
        color: color,
        angle: angle,
        distance: distance,
        speed: (0.002 + Math.random() * 0.002)
      });
    }

    let angleOffset = 0;
    let targetTiltX = 0;
    let targetTiltY = 0;

    const render = () => {
      ctx.fillStyle = 'rgba(11, 13, 23, 0.25)';
      ctx.fillRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;

      angleOffset += 0.003 * speed * (warpMode ? 4 : 1);

      // Smooth tilt from mouse position
      const tiltX = (mousePos.y / height - 0.5) * 0.8;
      const tiltY = (mousePos.x / width - 0.5) * 0.8;

      targetTiltX += (tiltX - targetTiltX) * 0.05;
      targetTiltY += (tiltY - targetTiltY) * 0.05;

      // Draw Galactic Core Glow
      const grad = ctx.createRadialGradient(centerX, centerY, 5, centerX, centerY, 140);
      grad.addColorStop(0, 'rgba(255, 235, 180, 0.9)');
      grad.addColorStop(0.2, 'rgba(78, 240, 208, 0.4)');
      grad.addColorStop(0.6, 'rgba(160, 96, 255, 0.15)');
      grad.addColorStop(1, 'rgba(11, 13, 23, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(centerX, centerY, 140, 0, Math.PI * 2);
      ctx.fill();

      // Render Stars with 3D Perspective
      stars.forEach((star) => {
        star.angle += star.speed * speed * (warpMode ? 3 : 1);
        const curDist = star.distance;

        let px = Math.cos(star.angle) * curDist;
        let py = Math.sin(star.angle) * curDist;
        let pz = star.z;

        // Apply 3D Perspective Rotation
        const cosX = Math.cos(targetTiltX);
        const sinX = Math.sin(targetTiltX);
        const cosY = Math.cos(targetTiltY);
        const sinY = Math.sin(targetTiltY);

        let rx = px * cosY - pz * sinY;
        let rz = px * sinY + pz * cosY;
        let ry = py * cosX - rz * sinX;

        const fov = 400;
        const scale = fov / (fov + rz + 200);

        const screenX = centerX + rx * scale;
        const screenY = centerY + ry * scale;

        if (screenX >= 0 && screenX <= width && screenY >= 0 && screenY <= height) {
          ctx.beginPath();
          ctx.arc(screenX, screenY, Math.max(0.5, star.size * scale), 0, Math.PI * 2);
          ctx.fillStyle = star.color;
          ctx.globalAlpha = Math.min(1, scale * 0.9);
          ctx.fill();
          ctx.globalAlpha = 1.0;
        }
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
    };
  }, [speed, warpMode, mousePos]);

  const handleMouseMove = (e) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (rect) {
      setMousePos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      });
    }
  };

  return (
    <div className="galaxy-page">
      <NavBar activeClass={["", "", "", "", "active"]} />

      <main className="container flow">
        <h1 className="numbered-title marginTop"><span>04</span> Space Galaxy Explorer</h1>

        <div className="galaxy-canvas-wrapper">
          <canvas 
            ref={canvasRef} 
            className="galaxy-canvas"
            onMouseMove={handleMouseMove}
          ></canvas>

          <div className="galaxy-hud flex">
            <div className="hud-control">
              <label className="ff-san-cond fs-200 uppercase letter-spacing-2">Rotation Speed:</label>
              <input 
                type="range" 
                min="0.2" 
                max="3" 
                step="0.1" 
                value={speed} 
                onChange={(e) => setSpeed(Number(e.target.value))}
                className="galaxy-slider" 
              />
              <span className="speed-val ff-serif">{speed}x</span>
            </div>

            <button 
              className={`warp-btn uppercase ff-san-cond fs-200 letter-spacing-2 ${warpMode ? 'active' : ''}`}
              onClick={() => setWarpMode(!warpMode)}
            >
              🚀 {warpMode ? 'Warp Drive ACTIVE' : 'Engage Warp Drive'}
            </button>
          </div>

          <div className="landmarks-panel grid">
            {GALAXY_LANDMARKS.map((lm) => (
              <button
                key={lm.id}
                className={`landmark-chip ${activeLandmark.id === lm.id ? 'active' : ''}`}
                onClick={() => setActiveLandmark(lm)}
                style={{ borderColor: lm.color }}
              >
                <span className="dot" style={{ backgroundColor: lm.color }}></span>
                <span className="ff-san-cond fs-200 uppercase letter-spacing-1">{lm.name}</span>
              </button>
            ))}
          </div>

          {activeLandmark && (
            <div className="landmark-info-card">
              <div className="card-header flex">
                <span className="landmark-badge uppercase ff-san-cond fs-200" style={{ color: activeLandmark.color, borderColor: activeLandmark.color }}>
                  Deep Space Sector
                </span>
                <span className="landmark-dist ff-san-cond fs-200">{activeLandmark.dist}</span>
              </div>
              <h3 className="ff-serif fs-700 uppercase" style={{ color: activeLandmark.color }}>
                {activeLandmark.name}
              </h3>
              <p className="ff-san-normal fs-300">
                {activeLandmark.desc}
              </p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
